// ECD Eventos — planejamento de casamentos, aniversários e eventos (demonstração estática)
// ECD Tecnologia · github.com/Du-Edu-Duarte
import { configureAuth, guard, authRoute, me } from './ecd-auth.js';
configureAuth({ name: 'ECD Eventos', tagline: 'Do orçamento à pista de dança, tudo do evento num só lugar.', bullets: ['Orçamento, fornecedores e parcelas', 'Convidados confirmam pelo celular', 'Cerimônia e playlist organizadas'], home: '#/' });

/* ---------------- utilidades ---------------- */
const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const uid = (n = 8) => [...crypto.getRandomValues(new Uint8Array(n))].map(b => 'abcdefghijkmnpqrstuvwxyz23456789'[b % 32]).join('');
const money = v => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v || 0);
const parseMoney = v => { const s = String(v || '').replace(/[^\d,.-]/g, ''); if (!s) return 0; return s.includes(',') ? parseFloat(s.replace(/\./g, '').replace(',', '.')) : parseFloat(s); };
const pad = n => String(n).padStart(2, '0');
const iso = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const today = () => iso(new Date());
const addDays = (s, n) => { const d = new Date(s + 'T12:00'); d.setDate(d.getDate() + n); return iso(d); };
const fmtD = s => s ? s.split('-').reverse().join('/') : '';
const fmtLong = s => s ? new Date(s + 'T12:00').toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).replace(/^./, c => c.toUpperCase()) : '';
const daysTo = s => Math.round((new Date(s + 'T12:00') - new Date(today() + 'T12:00')) / 864e5);
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const who = () => me()?.nome?.split(' ')[0] || '';
const ytId = u => (String(u || '').match(/(?:youtu\.be\/|v=|embed\/|shorts\/)([\w-]{11})/) || [])[1];
function toast(msg) { const t = $('#toast'); t.textContent = msg; t.hidden = false; clearTimeout(t._h); t._h = setTimeout(() => t.hidden = true, 2600); }
function download(data, name, type) { const url = URL.createObjectURL(new Blob([data], { type })); const a = document.createElement('a'); a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 4000); }
const csv = rows => '﻿' + rows.map(r => r.map(v => `"${String(v ?? '').replace(/"/g, '""')}"`).join(';')).join('\r\n');

/* ---------------- dados ---------------- */
const dbp = new Promise((res, rej) => { const r = indexedDB.open('ecd-eventos', 1); r.onupgradeneeded = () => r.result.createObjectStore('kv'); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
const idb = async (mode, fn) => { const d = await dbp; return new Promise((res, rej) => { const t = d.transaction('kv', mode); const o = fn(t.objectStore('kv')); t.oncomplete = () => res(o?.result); t.onerror = () => rej(t.error); }); };
let S = null;
const save = () => { clearTimeout(save._t); save._t = setTimeout(() => idb('readwrite', s => s.put(S, 'state')), 120); };
const ev = id => S.eventos.find(e => e.id === id);

/* ---------------- modelos por tipo de evento ---------------- */
const TIPOS = { casamento: 'Casamento', quinze: '15 anos', aniversario: 'Aniversário', corporativo: 'Corporativo', formatura: 'Formatura', outro: 'Outro' };
const CORES = ['#7a2e45', '#2f4a6d', '#2f6b4f', '#8a5a1f', '#5b3f8c', '#15110a'];
const CATS = ['Local / espaço', 'Buffet', 'Bebidas', 'Decoração e flores', 'Fotografia e vídeo', 'Música / DJ / banda', 'Cerimonial / assessoria', 'Vestuário e beleza', 'Convites e papelaria', 'Bolo e doces', 'Lembrancinhas', 'Outros'];
const TAREFAS = {
  casamento: [['12+ meses', ['Definir orçamento total', 'Escolher data e local', 'Fazer a primeira lista de convidados', 'Contratar cerimonial / assessoria']], ['6 a 12 meses', ['Contratar buffet', 'Contratar fotografia e vídeo', 'Contratar banda / DJ', 'Escolher padrinhos', 'Reservar o local da cerimônia']], ['3 a 6 meses', ['Enviar save the date', 'Definir decoração e flores', 'Provar o bolo e os doces', 'Escolher trajes', 'Definir as músicas da cerimônia']], ['1 a 3 meses', ['Enviar convites e abrir confirmação', 'Montar o mapa de mesas', 'Fazer a degustação do buffet', 'Abrir sugestões de músicas para a festa']], ['Última semana', ['Confirmar horários com todos os fornecedores', 'Passar o cronograma do dia para a equipe', 'Separar pagamentos finais', 'Ensaio da cerimônia']]],
  outro: [['3+ meses', ['Definir orçamento e data', 'Escolher e reservar o local', 'Fazer a lista de convidados']], ['1 a 3 meses', ['Contratar buffet e bebidas', 'Contratar música / DJ', 'Definir decoração', 'Enviar convites e abrir confirmação']], ['Última semana', ['Confirmar fornecedores', 'Fechar número de convidados com o buffet', 'Passar o cronograma do dia para a equipe']]],
};
const CRONO = {
  casamento: [['15:00', 'Chegada da equipe de decoração e cerimonial', 'Cerimonial'], ['16:30', 'Making of e fotos dos noivos', 'Fotografia'], ['17:30', 'Recepção dos convidados', 'Cerimonial'], ['18:00', 'Cerimônia', 'Celebrante'], ['18:45', 'Fotos com padrinhos e família', 'Fotografia'], ['19:15', 'Entrada dos noivos no salão', 'DJ'], ['19:30', 'Jantar', 'Buffet'], ['21:00', 'Bolo e brinde', 'Cerimonial'], ['21:15', 'Abertura da pista de dança', 'DJ'], ['01:00', 'Encerramento', 'Cerimonial']],
  outro: [['18:00', 'Montagem e decoração', 'Equipe'], ['19:00', 'Recepção dos convidados', 'Recepção'], ['20:00', 'Jantar', 'Buffet'], ['21:30', 'Parabéns / momento principal', 'Cerimonial'], ['22:00', 'Pista de dança', 'DJ'], ['00:30', 'Encerramento', 'Equipe']],
};
const ENTRADAS = [['Entrada do celebrante', ''], ['Entrada dos padrinhos', ''], ['Entrada do noivo', ''], ['Entrada das daminhas e pajens', ''], ['Entrada da noiva', ''], ['Alianças', ''], ['Assinaturas', ''], ['Saída dos noivos', '']];
function novoEvento({ nome, tipo, data, hora = '18:00', local = '', cor = CORES[0], orcamento = 0, convidadosPrev = 100 }) {
  const t = TAREFAS[tipo] || TAREFAS.outro; const c = CRONO[tipo] || CRONO.outro;
  return { id: uid(), nome, tipo, data, hora, local, cor, orcamento, convidadosPrev, token: uid(12), criadoEm: Date.now(), criadoPor: who(),
    fornecedores: [], convidados: [], tarefas: t.flatMap(([fase, ts]) => ts.map(titulo => ({ id: uid(), titulo, fase, feito: false, resp: '' }))),
    cronograma: c.map(([hora, titulo, resp]) => ({ id: uid(), hora, titulo, resp, local: '' })),
    cerimonia: { entradas: tipo === 'casamento' ? ENTRADAS.map(([momento]) => ({ id: uid(), momento, quem: '', musica: '', link: '', hora: '', obs: '' })) : [], equipe: [], traje: '', obs: '' },
    playlist: { aberta: true, max: 3, sugestoes: [], recado: 'Quais músicas não podem faltar na pista? Mande até 3!' } };
}

/* ---------------- cálculos ---------------- */
const contratado = e => e.fornecedores.filter(f => f.status === 'contratado').reduce((a, f) => a + f.valor, 0);
const pago = e => e.fornecedores.flatMap(f => f.parcelas).filter(p => p.pago).reduce((a, p) => a + p.valor, 0);
const confirmados = e => { const c = e.convidados.filter(g => g.status === 'sim'); return { pessoas: c.reduce((a, g) => a + g.adultos + g.criancas, 0), adultos: c.reduce((a, g) => a + g.adultos, 0), criancas: c.reduce((a, g) => a + g.criancas, 0) }; };
const convidadosTotal = e => e.convidados.reduce((a, g) => a + g.adultos + g.criancas, 0);
const tarefasPct = e => e.tarefas.length ? Math.round(e.tarefas.filter(t => t.feito).length / e.tarefas.length * 100) : 0;
const parcelasPend = e => e.fornecedores.flatMap(f => f.parcelas.filter(p => !p.pago).map(p => ({ ...p, f }))).sort((a, b) => a.venc.localeCompare(b.venc));

/* ---------------- modais ---------------- */
function modal(html, w = 600) { const md = $('#modal'); md.hidden = false; md.className = 'modal'; md.innerHTML = `<div class="box" style="width:min(${w}px,100%)">${html}</div>`; md.onclick = e => { if (e.target === md) close(); }; $$('[data-x]', md).forEach(b => b.onclick = close); return md; }
const close = () => { const md = $('#modal'); md.hidden = true; md.innerHTML = ''; md.onclick = null; };
function confirmBox(title, text, ok = 'Confirmar') { return new Promise(res => { const md = modal(`<h2 style="margin-bottom:8px">${esc(title)}</h2><p class="mut">${esc(text)}</p><div class="row" style="justify-content:flex-end;margin-top:16px"><button class="btn" data-a="n">Cancelar</button><button class="btn dark" data-a="y">${esc(ok)}</button></div>`, 440); md.onclick = e => { const a = e.target.closest('[data-a]')?.dataset.a; if (!a) return; close(); res(a === 'y'); }; }); }
function form(title, fields, onSave, { w = 560, del } = {}) {
  const md = modal(`<h2 style="margin-bottom:14px">${esc(title)}</h2><form class="formgrid">${fields.map(f => f.type === 'select' ? `<label class="f ${f.full ? 'full' : ''}">${esc(f.label)}<select name="${f.name}">${f.options.map(o => { const [v, t] = Array.isArray(o) ? o : [o, o]; return `<option value="${esc(v)}" ${String(v) === String(f.value) ? 'selected' : ''}>${esc(t)}</option>`; }).join('')}</select></label>` : f.type === 'textarea' ? `<label class="f full">${esc(f.label)}<textarea name="${f.name}" rows="${f.rows || 3}" placeholder="${esc(f.ph || '')}">${esc(f.value || '')}</textarea></label>` : `<label class="f ${f.full ? 'full' : ''}">${esc(f.label)}<input name="${f.name}" type="${f.type || 'text'}" value="${esc(f.value ?? '')}" placeholder="${esc(f.ph || '')}" ${f.req ? 'required' : ''} ${f.min != null ? `min="${f.min}"` : ''}></label>`).join('')}
    <div class="row full between">${del ? '<button type="button" class="btn" id="fDel">Excluir</button>' : '<span></span>'}<div class="row"><button type="button" class="btn" data-x>Cancelar</button><button class="btn primary">Salvar</button></div></div></form>`, w);
  const f = $('form', md); f.onsubmit = e => { e.preventDefault(); onSave(Object.fromEntries(new FormData(f))); close(); };
  if (del) $('#fDel').onclick = async () => { close(); if (await confirmBox('Excluir?', 'Esta ação não pode ser desfeita.', 'Excluir')) del(); };
  setTimeout(() => f.querySelector('input,select')?.focus(), 30);
}

/* ---------------- painel de eventos ---------------- */
const view = () => $('#view');
function Painel() {
  const evs = S.eventos.slice().sort((a, b) => a.data.localeCompare(b.data));
  const prox = evs.filter(e => daysTo(e.data) >= 0);
  view().innerHTML = `<div class="head"><div><div class="eyebrow">Seus eventos</div><h1>Tudo importante, em um só lugar.</h1><p class="mut" style="margin:6px 0 0">Orçamento, fornecedores, convidados, cronograma, cerimônia e playlist de cada evento.</p></div><a class="btn primary" href="#/novo">+ Novo evento</a></div>
  <div class="kpis"><div class="card kpi"><small>Próximos eventos</small><b>${prox.length}</b></div><div class="card kpi"><small>Convidados confirmados</small><b>${prox.reduce((a, e) => a + confirmados(e).pessoas, 0)}</b></div><div class="card kpi warn"><small>A pagar em fornecedores</small><b>${money(prox.reduce((a, e) => a + contratado(e) - pago(e), 0))}</b></div><div class="card kpi ok"><small>Tarefas concluídas</small><b>${prox.length ? Math.round(prox.reduce((a, e) => a + tarefasPct(e), 0) / prox.length) : 0}%</b></div></div>
  <div class="evgrid">${evs.map(e => { const d = daysTo(e.data); const c = confirmados(e); return `<a class="card evc" href="#/e/${e.id}" style="--c:${e.cor}"><div class="band"><small>${TIPOS[e.tipo]} · ${fmtD(e.data)}</small><h2>${esc(e.nome)}</h2></div><div class="body">
    <div class="row between"><div class="cd"><b>${d >= 0 ? d : '✓'}</b><span class="mut">${d > 0 ? (d === 1 ? 'dia' : 'dias') : d === 0 ? 'é hoje!' : 'realizado'}</span></div><div class="ring" style="--p:${tarefasPct(e)}"><span>${tarefasPct(e)}%</span></div></div>
    <div class="row between sm"><span class="mut">Convidados confirmados</span><b>${c.pessoas} de ${convidadosTotal(e) || e.convidadosPrev}</b></div>
    <div class="row between sm"><span class="mut">Pago aos fornecedores</span><b>${money(pago(e))} de ${money(contratado(e))}</b></div><div class="bar ok"><i style="width:${contratado(e) ? pago(e) / contratado(e) * 100 : 0}%;background:${e.cor}"></i></div></div></a>`; }).join('') || '<div class="card pad">Nenhum evento ainda.</div>'}</div>`;
}
function Novo() {
  view().innerHTML = `<div class="head"><div><div class="eyebrow">Novo evento</div><h1>Vamos começar.</h1><p class="mut" style="margin:6px 0 0">Escolha o tipo: as tarefas, o cronograma do dia e a ordem da cerimônia já vêm prontos para você ajustar.</p></div><a class="btn" href="#/">Voltar</a></div>
  <form id="fN" class="card pad formgrid" style="max-width:760px">
    <label class="f full">Nome do evento<input name="nome" required placeholder="Ex.: Casamento Ana & Pedro"></label>
    <label class="f">Tipo<select name="tipo">${Object.entries(TIPOS).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select></label>
    <label class="f">Data<input name="data" type="date" required value="${addDays(today(), 180)}"></label>
    <label class="f">Horário<input name="hora" type="time" value="18:00"></label>
    <label class="f">Local<input name="local" placeholder="Ex.: Espaço Jardim, Barueri"></label>
    <label class="f">Orçamento total (R$)<input name="orc" placeholder="Ex.: 45.000,00"></label>
    <label class="f">Convidados previstos<input name="prev" type="number" min="1" value="120"></label>
    <div class="f full">Cor do evento<div class="colorpick">${CORES.map((c, i) => `<input type="radio" name="cor" id="c${i}" value="${c}" ${i ? '' : 'checked'}><label for="c${i}" style="background:${c}"></label>`).join('')}</div></div>
    <div class="row full" style="justify-content:flex-end"><button class="btn primary">Criar evento →</button></div></form>`;
  $('#fN').onsubmit = e => { e.preventDefault(); const f = e.target; const n = novoEvento({ nome: f.nome.value.trim(), tipo: f.tipo.value, data: f.data.value, hora: f.hora.value, local: f.local.value, cor: f.cor.value, orcamento: parseMoney(f.orc.value), convidadosPrev: +f.prev.value }); S.eventos.push(n); save(); location.hash = `#/e/${n.id}`; toast('Evento criado com tarefas e cronograma prontos'); };
}

/* ---------------- evento ---------------- */
const TABS = [['geral', 'Visão geral'], ['orcamento', 'Orçamento e fornecedores'], ['convidados', 'Convidados'], ['tarefas', 'Tarefas'], ['cronograma', 'Cronograma do dia'], ['cerimonia', 'Cerimônia e músicos'], ['playlist', 'Playlist da festa'], ['ajustes', 'Ajustes']];
const pubLink = (e, kind) => `${location.origin}${location.pathname}#/${kind}/${e.id}/${e.token}`;
function shareBox(e, kind, label, msg) { const url = pubLink(e, kind); return `<div class="share"><span>🔗 <b>${label}</b> (abre sem login)</span><button class="btn sm" data-copy="${esc(url)}">Copiar link</button><a class="btn sm wa" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(msg + '\n' + url)}">WhatsApp</a><a class="btn sm" href="${url}" target="_blank" rel="noopener">Abrir</a></div>`; }
const bindCopy = () => $$('[data-copy]').forEach(b => b.onclick = async () => { try { await navigator.clipboard.writeText(b.dataset.copy); toast('Link copiado'); } catch { toast(b.dataset.copy); } });
function Evento(id, tab = 'geral') {
  const e = ev(id); if (!e) return view().innerHTML = '<div class="card pad"><h2>Evento não encontrado</h2><a class="btn" href="#/">Voltar</a></div>';
  const d = daysTo(e.data);
  view().innerHTML = `<div style="--c:${e.cor}"><div class="ev-head"><div><div class="eyebrow">${TIPOS[e.tipo]}${e.local ? ' · ' + esc(e.local) : ''}</div><h1>${esc(e.nome)}</h1><div class="mut" style="margin-top:6px;">${fmtLong(e.data)}${e.hora ? ' · ' + e.hora : ''}</div></div>
    <div class="row"><a class="btn sm" href="#/">← Eventos</a><div class="count"><b>${d >= 0 ? d : '✓'}</b><span class="sm">${d > 0 ? 'dias para o evento' : d === 0 ? 'é hoje!' : 'evento realizado'}</span></div></div></div>
    <nav class="tabs">${TABS.map(([k, t]) => `<a href="#/e/${e.id}/${k}" class="${tab === k ? 'on' : ''}">${t}</a>`).join('')}</nav><div id="tab"></div></div>`;
  ({ geral: Geral, orcamento: Orcamento, convidados: Convidados, tarefas: Tarefas, cronograma: Cronograma, cerimonia: Cerimonia, playlist: Playlist, ajustes: AjustesEv }[tab] || Geral)(e);
  bindCopy();
}
const T = () => $('#tab');
const rerender = e => { save(); const h = location.hash.split('/'); Evento(e.id, h[3] || 'geral'); };
function Geral(e) {
  const c = confirmados(e), ct = contratado(e), pg = pago(e), pend = parcelasPend(e), disp = e.orcamento - ct;
  const nextT = e.tarefas.filter(t => !t.feito).slice(0, 5); const vencidas = pend.filter(p => p.venc < today());
  const sug = e.playlist.sugestoes.length; const resp = e.convidados.filter(g => g.status !== 'pend').length;
  T().innerHTML = `<div class="kpis">
    <div class="card kpi"><small>Total contratado</small><b>${money(ct)}</b><div class="sub">${e.fornecedores.filter(f => f.status === 'contratado').length} fornecedores</div></div>
    <div class="card kpi ok"><small>Já pago</small><b>${money(pg)}</b><div class="sub">${ct ? Math.round(pg / ct * 100) : 0}% do contratado</div></div>
    <div class="card kpi warn"><small>Falta pagar</small><b>${money(ct - pg)}</b><div class="sub">${vencidas.length ? `<span class="neg">${vencidas.length} parcela(s) vencida(s)</span>` : `${pend.length} parcelas a vencer`}</div></div>
    <div class="card kpi info"><small>Confirmados</small><b>${c.pessoas}</b><div class="sub">${c.adultos} adultos · ${c.criancas} crianças · ${resp}/${e.convidados.length} responderam</div></div></div>
  <div class="g2"><div class="card pad"><div class="row between"><h2>Orçamento</h2><button class="btn sm" id="edOrc">Editar orçamento</button></div>
      <div class="row between" style="margin-top:14px"><span class="mut">Contratado ${money(ct)} de ${money(e.orcamento)}</span><b class="${disp < 0 ? 'neg' : 'pos'}">${disp < 0 ? 'Passou ' + money(-disp) : 'Disponível ' + money(disp)}</b></div>
      <div class="bar ${disp < 0 ? 'over' : ct / (e.orcamento || 1) > .9 ? 'warn' : 'ok'}"><i style="width:${Math.min(100, e.orcamento ? ct / e.orcamento * 100 : 0)}%"></i></div>
      ${!e.orcamento ? '<p class="tip" style="margin-top:12px">Defina o orçamento total para acompanhar quanto ainda está disponível.</p>' : ''}
      <h3 style="margin:18px 0 6px">Próximos pagamentos</h3><div class="due">${pend.slice(0, 5).map(p => `<div class="it"><div class="dd"><b>${p.venc.slice(8)}</b><small>${new Date(p.venc + 'T12:00').toLocaleDateString('pt-BR', { month: 'short' }).replace('.', '')}</small></div><div><b>${esc(p.f.nome)}</b><div class="mut sm">${esc(p.desc)} · ${esc(p.f.categoria)}</div></div><div style="text-align:right"><div class="amt">${money(p.valor)}</div><button class="st ${p.venc < today() ? 'atrasado' : p.venc === today() ? 'hoje' : 'avencer'}" data-pp="${p.f.id}:${p.id}">${p.venc < today() ? 'Vencida' : 'Pagar'}</button></div></div>`).join('') || '<p class="mut sm">Nenhuma parcela pendente.</p>'}</div></div>
    <div class="grid"><div class="card pad" style="background:${e.cor};color:#fff;border:0"><div class="row between"><div><div class="eyebrow" style="color:rgba(255,255,255,.75)">Andamento</div><div style="font-size:36px;font-weight:800">${tarefasPct(e)}%</div><div class="sm" style="opacity:.85">${e.tarefas.filter(t => t.feito).length} de ${e.tarefas.length} tarefas</div></div><div class="ring" style="--p:${tarefasPct(e)};--c:#fff;background:conic-gradient(#fff calc(${tarefasPct(e)}*1%),rgba(255,255,255,.25) 0)"><span style="background:${e.cor};color:#fff">✓</span></div></div>
      <div style="background:rgba(255,255,255,.12);border-radius:12px;padding:12px;margin-top:14px"><div class="eyebrow" style="color:rgba(255,255,255,.7);margin-bottom:6px">Próximo foco</div>${nextT.slice(0, 3).map(t => `<div class="sm" style="padding:3px 0">• ${esc(t.titulo)} <span style="opacity:.7">(${esc(t.fase)})</span></div>`).join('') || '<div class="sm">Tudo pronto! 🎉</div>'}</div></div>
      <div class="card pad"><h3 style="margin-bottom:10px">Links para compartilhar</h3><div class="grid" style="gap:8px">${shareBox(e, 'rsvp', 'Confirmação de presença', `Você está convidado(a) para ${e.nome}! Confirme sua presença:`)}${shareBox(e, 'musicas', `Sugestão de músicas (${sug})`, `Ajude a montar a playlist de ${e.nome}! Sugira suas músicas:`)}${e.cerimonia.entradas.length ? shareBox(e, 'guia', 'Guia dos músicos', `Guia da cerimônia de ${e.nome}:`) : ''}</div></div></div></div>`;
  $('#edOrc').onclick = () => form('Orçamento total', [{ name: 'o', label: 'Valor (R$)', value: String(e.orcamento).replace('.', ',') }], v => { e.orcamento = parseMoney(v.o); rerender(e); });
  bindPayButtons(e);
}
function bindPayButtons(e) { $$('[data-pp]').forEach(b => b.onclick = async () => { const [fid, pid] = b.dataset.pp.split(':'); const f = e.fornecedores.find(x => x.id === fid); const p = f.parcelas.find(x => x.id === pid); if (p.pago) { p.pago = null; rerender(e); return; } p.pago = { data: today(), por: who() }; rerender(e); toast('Parcela marcada como paga'); }); }
